//! #99: export commands — destination picker, artifact file writes,
//! tool detection, explorer reveal and MuseScore PDF rendering.
//!
//! Self-limiting model (same posture as lib.rs's read commands): the
//! frontend cannot write anywhere it likes. A destination directory is
//! writable only when it
//!   - was picked through `export_pick_dir` this session, or
//!   - lives under the OS Documents directory.
//! File names are restricted to the export artifact extensions
//! (.musicxml/.xml/.mid/.pdf) and may not contain path separators, so
//! the command can never escape the destination directory.

use std::collections::HashSet;
use std::path::{Path, PathBuf};
use std::sync::Mutex;

use serde::{Deserialize, Serialize};
use tauri::Manager;
use tauri_plugin_dialog::DialogExt;

/// Artifact extensions the export flow may write (§17 formats).
const EXPORT_EXTENSIONS: [&str; 4] = ["musicxml", "xml", "mid", "pdf"];

/// Directories the user explicitly picked via `export_pick_dir` this
/// session — the write side of the self-limiting model.
static GRANTED_DIRS: Mutex<Option<HashSet<PathBuf>>> = Mutex::new(None);

fn grant_dir(dir: PathBuf) {
    let mut guard = GRANTED_DIRS.lock().unwrap_or_else(|e| e.into_inner());
    guard.get_or_insert_with(HashSet::new).insert(dir);
}

/// One artifact to write: file name + base64 payload (NDJSON-safe).
#[derive(Deserialize)]
#[serde(rename_all = "camelCase")]
pub struct ExportFile {
    pub name: String,
    pub data_base64: String,
}

/// `export_pick_dir`: native folder picker (Rust-side dialog plugin — no
/// JS plugin permission needed). A picked directory is granted write
/// access for the rest of the session; returns null on cancel.
#[tauri::command]
pub fn export_pick_dir(
    app: tauri::AppHandle,
    current: Option<String>,
) -> Result<Option<String>, String> {
    let mut dlg = app.dialog().file();
    if let Some(dir) = current {
        let p = PathBuf::from(&dir);
        if p.is_dir() {
            dlg = dlg.set_directory(p);
        }
    }
    let Some(path) = dlg.blocking_pick_folder() else {
        return Ok(None);
    };
    let dir = path
        .as_path()
        .map(|p| p.to_path_buf())
        .ok_or("picked path is not a filesystem path")?;
    grant_dir(dir.clone());
    Ok(Some(dir.to_string_lossy().into_owned()))
}

/// `export_default_dir`: `<Documents>/HornScribe` (reported without
/// creating — the dialog shows the path before anything is written).
#[tauri::command]
pub fn export_default_dir(app: tauri::AppHandle) -> Result<String, String> {
    let docs = app
        .path()
        .document_dir()
        .map_err(|e| format!("document dir: {e}"))?;
    let dir = docs.join("HornScribe");
    Ok(dir.to_string_lossy().into_owned())
}

/// Whether `dir` is a legal export destination: picked this session or
/// under the OS Documents directory.
fn dir_allowed(app: &tauri::AppHandle, dir: &Path) -> bool {
    if let Ok(guard) = GRANTED_DIRS.lock() {
        if let Some(set) = guard.as_ref() {
            if set.contains(dir) {
                return true;
            }
        }
    }
    if let Ok(docs) = app.path().document_dir() {
        if dir.starts_with(&docs) {
            return true;
        }
    }
    false
}

/// Validate one artifact file name: no separators, allowlisted
/// extension, non-empty stem.
fn valid_export_name(name: &str) -> bool {
    let path = Path::new(name);
    if path.file_name().and_then(|n| n.to_str()) != Some(name) {
        return false;
    }
    let ext = path
        .extension()
        .and_then(|e| e.to_str())
        .unwrap_or_default()
        .to_ascii_lowercase();
    EXPORT_EXTENSIONS.contains(&ext.as_str())
        && path
            .file_stem()
            .and_then(|s| s.to_str())
            .is_some_and(|s| !s.is_empty())
}

/// `export_write_files`: write the export artifacts into `dir`.
/// Creates the directory when missing; overwrites same-named artifacts
/// (a re-export is an explicit user action). Fails with
/// `PERMISSION_DENIED` for un-granted destinations.
#[tauri::command]
pub fn export_write_files(
    app: tauri::AppHandle,
    dir: String,
    files: Vec<ExportFile>,
) -> Result<Vec<String>, String> {
    let dir_path = PathBuf::from(&dir);
    if !dir_allowed(&app, &dir_path) {
        return Err("PERMISSION_DENIED".to_string());
    }
    std::fs::create_dir_all(&dir_path)
        .map_err(|e| format!("create {}: {e}", dir_path.display()))?;
    let mut written = Vec::with_capacity(files.len());
    for file in files {
        if !valid_export_name(&file.name) {
            return Err(format!("invalid export name: {}", file.name));
        }
        let bytes = decode_base64(&file.data_base64)
            .map_err(|e| format!("{}: {e}", file.name))?;
        let path = dir_path.join(&file.name);
        std::fs::write(&path, &bytes)
            .map_err(|e| format!("write {}: {e}", path.display()))?;
        written.push(path.to_string_lossy().into_owned());
    }
    Ok(written)
}

/// `export_copy_audio`: copy the source audio file into the export
/// destination (#87 成果物同梱 — a recording→score bundle carries its
/// own audio). Reads `src` (user-owned, never modified) and writes
/// `dir/<basename>.<ext>` where `ext` is the source's own extension;
/// the destination dir is gated by the same allowlist as
/// `export_write_files`, and the file name is sanitized to a stem plus
/// a known audio extension so the command cannot write anything but
/// an audio artifact.
#[tauri::command]
pub fn export_copy_audio(
    app: tauri::AppHandle,
    src: String,
    dir: String,
    basename: String,
) -> Result<String, String> {
    const AUDIO_EXTENSIONS: [&str; 5] = ["wav", "mp3", "flac", "m4a", "ogg"];
    let src_path = PathBuf::from(&src);
    if !src_path.is_file() {
        return Err(format!("source audio not found: {src}"));
    }
    let ext = src_path
        .extension()
        .and_then(|e| e.to_str())
        .unwrap_or_default()
        .to_ascii_lowercase();
    if !AUDIO_EXTENSIONS.contains(&ext.as_str()) {
        return Err(format!("unsupported audio extension: {ext}"));
    }
    let dir_path = PathBuf::from(&dir);
    if !dir_allowed(&app, &dir_path) {
        return Err("PERMISSION_DENIED".to_string());
    }
    std::fs::create_dir_all(&dir_path)
        .map_err(|e| format!("create {}: {e}", dir_path.display()))?;
    let stem: String = basename
        .chars()
        .map(|c| match c {
            '\\' | '/' | ':' | '*' | '?' | '"' | '<' | '>' | '|' | '.' => '_',
            _ => c,
        })
        .collect::<String>()
        .trim()
        .to_string();
    let stem = if stem.is_empty() { "audio" } else { &stem };
    let dest = dir_path.join(format!("{stem}.{ext}"));
    std::fs::copy(&src_path, &dest)
        .map_err(|e| format!("copy {}: {e}", dest.display()))?;
    Ok(dest.to_string_lossy().into_owned())
}

/// `detect_tools`: probe MuseScore/ffmpeg for the export + diagnostics
/// surfaces. PATH first, then the standard MuseScore install dirs.
#[tauri::command]
pub fn detect_tools() -> DetectedTools {
    DetectedTools {
        muse_score: probe_tool(
            &["MuseScore4", "MuseScore3", "musescore"],
            &[
                r"C:\Program Files\MuseScore 4\bin\MuseScore4.exe",
                r"C:\Program Files\MuseScore 3\bin\MuseScore3.exe",
                r"C:\Program Files (x86)\MuseScore 4\bin\MuseScore4.exe",
            ],
        ),
        ffmpeg: probe_tool(&["ffmpeg"], &[]),
    }
}

#[derive(Serialize)]
#[serde(rename_all = "camelCase")]
pub struct DetectedTools {
    pub muse_score: ToolProbe,
    pub ffmpeg: ToolProbe,
}

#[derive(Serialize)]
#[serde(rename_all = "camelCase")]
pub struct ToolProbe {
    pub status: String, // "found" | "missing"
    #[serde(skip_serializing_if = "Option::is_none")]
    pub path: Option<String>,
}

fn probe_tool(path_names: &[&str], absolute_candidates: &[&str]) -> ToolProbe {
    for name in path_names {
        if which_exists(name) {
            return ToolProbe {
                status: "found".into(),
                path: Some((*name).to_string()),
            };
        }
    }
    for candidate in absolute_candidates {
        if Path::new(candidate).is_file() {
            return ToolProbe {
                status: "found".into(),
                path: Some((*candidate).to_string()),
            };
        }
    }
    ToolProbe {
        status: "missing".into(),
        path: None,
    }
}

fn which_exists(exe: &str) -> bool {
    std::process::Command::new("where")
        .arg(exe)
        .stdout(std::process::Stdio::null())
        .stderr(std::process::Stdio::null())
        .status()
        .map(|s| s.success())
        .unwrap_or(false)
}

/// `reveal_in_explorer`: open a directory in the OS file manager.
#[tauri::command]
pub fn reveal_in_explorer(path: String) -> Result<(), String> {
    let p = PathBuf::from(&path);
    if !p.is_dir() {
        return Err(format!("not a directory: {path}"));
    }
    std::process::Command::new("explorer")
        .arg(&p)
        .spawn()
        .map_err(|e| format!("explorer {}: {e}", p.display()))?;
    Ok(())
}

/// `project_save_path`: native save-file picker for `.hornscribe.json`
/// (#100). The picked file's parent directory is granted write access
/// (same model as `export_pick_dir`); returns null on cancel.
#[tauri::command]
pub fn project_save_path(
    app: tauri::AppHandle,
    suggested_name: Option<String>,
) -> Result<Option<String>, String> {
    let mut dlg = app
        .dialog()
        .file()
        .add_filter("HornScribe プロジェクト", &["hornscribe.json"]);
    if let Some(name) = suggested_name {
        if !name.is_empty() {
            dlg = dlg.set_file_name(&name);
        }
    }
    let Some(path) = dlg.blocking_save_file() else {
        return Ok(None);
    };
    let file = path
        .as_path()
        .map(|p| p.to_path_buf())
        .ok_or("picked path is not a filesystem path")?;
    if let Some(parent) = file.parent() {
        grant_dir(parent.to_path_buf());
    }
    // The dialog may return the name without the suffix the filter
    // describes — append it so the worker's path check never trips
    // on a user-typed name.
    let file = if file.to_string_lossy().ends_with(".hornscribe.json") {
        file
    } else {
        let mut name = file
            .file_name()
            .unwrap_or_default()
            .to_string_lossy()
            .into_owned();
        // "take.json" → "take"; "take.hornscribe" → "take"
        for suffix in [".hornscribe.json", ".hornscribe", ".json"] {
            if let Some(stripped) = name.strip_suffix(suffix) {
                name = stripped.to_string();
                break;
            }
        }
        file.with_file_name(format!("{name}.hornscribe.json"))
    };
    Ok(Some(file.to_string_lossy().into_owned()))
}

/// `render_pdf`: run MuseScore headless (`-o out.pdf score.musicxml`).
/// The MusicXML arrives as text; it is staged in the temp dir, rendered,
/// then removed. `out_path` must satisfy the same destination rules as
/// `export_write_files`.
#[tauri::command]
pub fn render_pdf(
    app: tauri::AppHandle,
    musescore_path: String,
    music_xml: String,
    out_path: String,
) -> Result<String, String> {
    let exe = PathBuf::from(&musescore_path);
    if !exe.is_file() {
        return Err("MUSESCORE_UNAVAILABLE".to_string());
    }
    let out = PathBuf::from(&out_path);
    let parent = out.parent().ok_or("out path has no directory")?;
    if !dir_allowed(&app, parent) {
        return Err("PERMISSION_DENIED".to_string());
    }
    if out.extension().and_then(|e| e.to_str()) != Some("pdf") {
        return Err("out path must end in .pdf".to_string());
    }
    std::fs::create_dir_all(parent)
        .map_err(|e| format!("create {}: {e}", parent.display()))?;

    let staging = std::env::temp_dir().join(format!(
        "hornscribe-export-{}-{}.musicxml",
        std::process::id(),
        out.file_stem().and_then(|s| s.to_str()).unwrap_or("score")
    ));
    std::fs::write(&staging, music_xml.as_bytes())
        .map_err(|e| format!("stage {}: {e}", staging.display()))?;

    let status = std::process::Command::new(&exe)
        .args(["-o"])
        .arg(&out)
        .arg(&staging)
        .stdout(std::process::Stdio::null())
        .stderr(std::process::Stdio::null())
        .status();
    let _ = std::fs::remove_file(&staging);
    match status {
        Ok(s) if s.success() && out.is_file() => {
            Ok(out.to_string_lossy().into_owned())
        }
        Ok(s) => Err(format!("MuseScore exited with {s}")),
        Err(e) => Err(format!("spawn {}: {e}", exe.display())),
    }
}

/// `open_in_musescore`: stage the score as a temp MusicXML and launch the
/// MuseScore GUI on it (spec 13: 高度編集 → MuseScoreで開く). Unlike
/// `render_pdf` the process is not awaited — the user keeps working in
/// MuseScore — so the staged file is left for the OS temp cleaner.
/// A millisecond suffix keeps successive opens (edited score re-opens)
/// from overwriting a file the GUI may still hold.
#[tauri::command]
pub fn open_in_musescore(
    musescore_path: String,
    music_xml: String,
    basename: String,
) -> Result<String, String> {
    let exe = PathBuf::from(&musescore_path);
    if !exe.is_file() {
        return Err("MUSESCORE_UNAVAILABLE".to_string());
    }
    let stem_raw: String = basename
        .chars()
        .map(|c| {
            if c.is_alphanumeric() || c == '-' || c == '_' {
                c
            } else {
                '_'
            }
        })
        .collect();
    let stem: &str = if stem_raw.is_empty() { "score" } else { &stem_raw };
    let millis = std::time::SystemTime::now()
        .duration_since(std::time::UNIX_EPOCH)
        .map(|d| d.as_millis())
        .unwrap_or(0);
    let staging = std::env::temp_dir().join(format!(
        "hornscribe-open-{}-{}.musicxml",
        stem,
        millis
    ));
    std::fs::write(&staging, music_xml.as_bytes())
        .map_err(|e| format!("stage {}: {e}", staging.display()))?;
    std::process::Command::new(&exe)
        .arg(&staging)
        .stdout(std::process::Stdio::null())
        .stderr(std::process::Stdio::null())
        .spawn()
        .map_err(|e| format!("spawn {}: {e}", exe.display()))?;
    Ok(staging.to_string_lossy().into_owned())
}

/// Minimal RFC 4648 decoder — avoids a base64 dependency for a
/// few-hundred-KB worst-case payload.
fn decode_base64(input: &str) -> Result<Vec<u8>, String> {
    fn val(b: u8) -> Result<u8, String> {
        match b {
            b'A'..=b'Z' => Ok(b - b'A'),
            b'a'..=b'z' => Ok(b - b'a' + 26),
            b'0'..=b'9' => Ok(b - b'0' + 52),
            b'+' => Ok(62),
            b'/' => Ok(63),
            _ => Err(format!("bad base64 byte {b}")),
        }
    }
    let bytes: Vec<u8> = input
        .bytes()
        .filter(|b| !b.is_ascii_whitespace())
        .collect();
    if bytes.len() % 4 != 0 {
        return Err("base64 length not a multiple of 4".into());
    }
    let mut out = Vec::with_capacity(bytes.len() / 4 * 3);
    for chunk in bytes.chunks(4) {
        let pad = chunk.iter().rev().take_while(|&&b| b == b'=').count();
        if pad > 2 {
            return Err("too much base64 padding".into());
        }
        let mut acc: u32 = 0;
        for (i, &b) in chunk.iter().enumerate() {
            let v = if b == b'=' { 0 } else { val(b)? };
            acc |= (v as u32) << (18 - i * 6);
        }
        out.push((acc >> 16) as u8);
        if pad < 2 {
            out.push((acc >> 8) as u8);
        }
        if pad < 1 {
            out.push(acc as u8);
        }
    }
    Ok(out)
}

//! HornScribe desktop shell — UI-001 spike + UI-020 import plumbing.
//!
//! Security model: no fs/asset-protocol/shell/http grants. The only plugin
//! is `tauri-plugin-dialog`, capability-scoped to `dialog:allow-open` so the
//! frontend can show the native picker (no save/message variants granted).
//!
//! Because the ACL does not govern app-defined commands, the file-reading
//! commands below self-limit instead of relying on a permission grant:
//! `read_audio_bytes` serves only the advertised audio extensions with a
//! hard size cap, and `read_project_file` serves only `*.hornscribe.json`
//! project documents. Both are read-only — the source file is never
//! modified (GUI_UX_SPEC §3 / FND-001 SourceAudioRef).

use serde::Serialize;

mod capture;
mod engine;
mod export;

/// Audio containers the import UX advertises (GUI_UX_SPEC §3 formats line).
/// The frontend rejects other extensions before reaching this command; the
/// allowlist here is the Rust-side backstop so the command cannot be turned
/// into a general file reader.
const AUDIO_EXTENSIONS: [&str; 5] = ["wav", "mp3", "flac", "m4a", "ogg"];

/// HornScribe project document suffix (python/hornscribe/project/model.py).
const PROJECT_FILE_SUFFIX: &str = ".hornscribe.json";

/// 512 MiB — far above any realistic horn recording (~90 MB for 10 min of
/// PCM16 stereo 44.1 kHz); guards against unbounded reads.
const MAX_AUDIO_BYTES: u64 = 512 * 1024 * 1024;
/// Project JSON is a small manifest; 16 MiB is already generous.
const MAX_PROJECT_BYTES: u64 = 16 * 1024 * 1024;

#[derive(Serialize)]
#[serde(rename_all = "camelCase")]
struct ShellInfo {
    app_name: String,
    version: String,
    rust_target_env: String,
}

#[tauri::command]
fn shell_info(app: tauri::AppHandle) -> ShellInfo {
    let pkg = app.package_info();
    ShellInfo {
        app_name: pkg.name.clone(),
        version: pkg.version.to_string(),
        rust_target_env: (if cfg!(target_env = "msvc") {
            "msvc"
        } else if cfg!(target_env = "gnu") {
            "gnu"
        } else {
            "other"
        })
        .to_string(),
    }
}

/// Read a user-selected audio file and return its bytes over raw IPC so the
/// webview can decode it (WebAudio `decodeAudioData`) and hash it
/// (WebCrypto SHA-256, mirroring `hash_file_sha256` in the project schema).
/// Read-only, extension-allowlisted, size-capped.
#[tauri::command]
fn read_audio_bytes(path: String) -> Result<tauri::ipc::Response, String> {
    let ext = std::path::Path::new(&path)
        .extension()
        .and_then(|e| e.to_str())
        .unwrap_or_default()
        .to_ascii_lowercase();
    if !AUDIO_EXTENSIONS.contains(&ext.as_str()) {
        return Err(format!("unsupported audio extension: {ext}"));
    }
    let meta = std::fs::metadata(&path).map_err(|e| format!("{path}: {e}"))?;
    if !meta.is_file() {
        return Err(format!("not a file: {path}"));
    }
    if meta.len() > MAX_AUDIO_BYTES {
        return Err(format!("audio file too large: {} bytes", meta.len()));
    }
    let bytes = std::fs::read(&path).map_err(|e| format!("{path}: {e}"))?;
    Ok(tauri::ipc::Response::new(bytes))
}

/// Read a `*.hornscribe.json` project document (schema v1, FND-001) so the
/// import flow can recover sourceAudio.originalPath/contentHash for the
/// relink UX. Read-only, suffix-restricted, size-capped.
#[tauri::command]
fn read_project_file(path: String) -> Result<tauri::ipc::Response, String> {
    if !path.to_ascii_lowercase().ends_with(PROJECT_FILE_SUFFIX) {
        return Err(format!("not a HornScribe project file: {path}"));
    }
    let meta = std::fs::metadata(&path).map_err(|e| format!("{path}: {e}"))?;
    if !meta.is_file() {
        return Err(format!("not a file: {path}"));
    }
    if meta.len() > MAX_PROJECT_BYTES {
        return Err(format!("project file too large: {} bytes", meta.len()));
    }
    let bytes = std::fs::read(&path).map_err(|e| format!("{path}: {e}"))?;
    Ok(tauri::ipc::Response::new(bytes))
}

#[cfg_attr(mobile, tauri::mobile_entry_point)]
pub fn run() {
    tauri::Builder::default()
        .plugin(tauri_plugin_dialog::init())
        .invoke_handler(tauri::generate_handler![
            shell_info,
            read_audio_bytes,
            read_project_file,
            capture::capture_start,
            capture::capture_stop,
            capture::capture_cancel,
            capture::capture_status,
            capture::capture_devices,
            capture::capture_pause,
            capture::capture_resume,
            capture::recordings_info,
            capture::open_recordings_dir,
            capture::clear_recordings,
            capture::recordings_list,
            capture::delete_recording,
            engine::engine_spawn,
            engine::engine_write,
            engine::engine_close_stdin,
            engine::engine_kill,
            export::export_pick_dir,
            export::export_default_dir,
            export::export_write_files,
            export::export_copy_audio,
            export::detect_tools,
            export::reveal_in_explorer,
            export::render_pdf,
            export::project_save_path,
            export::open_in_musescore,
        ])
        .build(tauri::generate_context!())
        .expect("error while building HornScribe shell")
        .run(|_app, event| {
            if let tauri::RunEvent::Exit = event {
                engine::kill_engine_on_exit();
            }
        });
}

