 * Pure logic — no DOM needed.
 */

import { describe, expect, it, vi } from "vitest";
import { ja } from "../strings/ja";
import { CommandRegistry, createCommandRegistry } from "./registry";
import type {
  Command,
  CommandContext,
  CommandSnapshot,
} from "./types";

const SNAPSHOT_EMPTY: CommandSnapshot = {
  hasAudio: false,
  hasScore: false,
  isTranscribing: false,
  isPlaying: false,
  loopEnabled: false,
  pitch: "concert",
  canUndo: false,
  canRedo: false,
  hasSelection: false,
  hasWaveformSelection: false,
  reviewOpen: false,
  reviewCount: 0,
      isRecording: false,
      isRecordingPaused: false,
      auditionEnabled: false,
  view: "workspace",
};

const SNAPSHOT_SCORE: CommandSnapshot = {
  ...SNAPSHOT_EMPTY,
  hasAudio: true,
  hasScore: true,
  canUndo: true,
  canRedo: true,
  hasSelection: true,
  reviewCount: 3,
      isRecording: false,
      isRecordingPaused: false,
      auditionEnabled: false,
};

function mockContext(): CommandContext & { calls: string[] } {
  const calls: string[] = [];
  const spy = (name: string) => vi.fn(() => calls.push(name));
  return {
    calls,
    openAudio: spy("openAudio"),
    transcribe: spy("transcribe"),
    togglePlayPause: spy("togglePlayPause"),
    stop: spy("stop"),
    jumpBack: spy("jumpBack"),
    jumpForward: spy("jumpForward"),
    seekToStart: spy("seekToStart"),
    seekToEnd: spy("seekToEnd"),
    toggleLoop: spy("toggleLoop"),
    setPitchView: spy("setPitchView"),
    openReview: spy("openReview"),
    reviewNext: spy("reviewNext"),
    reviewPrevious: spy("reviewPrevious"),
    undo: spy("undo"),
    redo: spy("redo"),
    openExport: spy("openExport"),
    openInMuseScore: spy("openInMuseScore"),
    zoomScoreIn: spy("zoomScoreIn"),
    zoomScoreOut: spy("zoomScoreOut"),
    zoomScoreFit: spy("zoomScoreFit"),
    clearSelection: spy("clearSelection"),
    openSettings: spy("openSettings"),
    openDiagnostics: spy("openDiagnostics"),
    focusNextRegion: spy("focusNextRegion"),
    focusPreviousRegion: spy("focusPreviousRegion"),
    announce: spy("announce"),
  };
}

describe("command definitions", () => {
  const registry = createCommandRegistry();

  it("covers every command required by UI-012 / GUI_UX_SPEC", () => {
    const ids = registry.list().map((c) => c.id);
    for (const required of [
      "file.openAudio",
      "score.transcribe",
      "transport.playPause",
      "transport.stop",
      "transport.jumpBack",
      "transport.jumpForward",
      "transport.toggleLoop",
      "view.concertPitch",
      "view.hornF",
      "review.open",
      "review.next",
      "review.previous",
      "review.playSource",
      "review.accept",
      "review.dismiss",
      "review.pitchUp",
      "review.pitchDown",
      "review.deleteOrRestore",
      "review.exit",
      "edit.undo",
      "edit.redo",
      "export.open",
      "export.openInMuseScore",
      "score.zoomIn",
      "score.zoomOut",
      "score.zoomFit",
      "nav.nextRegion",
      "nav.previousRegion",
      "app.settings",
      "app.diagnostics",
    ]) {
      expect(ids).toContain(required);
    }
  });

  it("ships with zero shortcut conflicts", () => {
    expect(registry.detectConflicts()).toEqual([]);
  });

  it("every command has a non-empty Japanese title", () => {
    const known = new Set<string>(Object.values(ja.commands));
    for (const command of registry.list()) {
      expect(command.title.length).toBeGreaterThan(0);
      // Titles come from the shared copy module, not ad-hoc strings.
      expect(known.has(command.title)).toBe(true);
    }
  });

  it("initial bindings match the spec table (§9, §15, §22)", () => {
    const shortcutOf = (id: string) =>
      registry.get(id)?.shortcuts ?? [];
    expect(shortcutOf("file.openAudio")).toContain("Ctrl+O");
    expect(shortcutOf("transport.playPause")).toEqual(
      expect.arrayContaining(["Space", "K"]),
    );
    expect(shortcutOf("transport.stop")).toContain("Shift+Space");
    expect(shortcutOf("transport.jumpBack")).toContain("J");
    expect(shortcutOf("transport.jumpForward")).toContain("L");
    expect(shortcutOf("transport.toggleLoop")).toContain("Ctrl+L");
    expect(shortcutOf("view.concertPitch")).toContain("Ctrl+1");
    expect(shortcutOf("view.hornF")).toContain("Ctrl+2");
    expect(shortcutOf("edit.undo")).toContain("Ctrl+Z");
    expect(shortcutOf("edit.redo")).toContain("Ctrl+Shift+Z");
    // UI-050 review keys (P4-validated set).
    expect(shortcutOf("review.next")).toContain("ArrowRight");
    expect(shortcutOf("review.previous")).toContain("ArrowLeft");
    expect(shortcutOf("review.playSource")).toContain("R");
    expect(shortcutOf("review.accept")).toContain("O");
    expect(shortcutOf("review.dismiss")).toContain("Shift+O");
    expect(shortcutOf("review.pitchUp")).toContain("Alt+ArrowUp");
    expect(shortcutOf("review.pitchDown")).toContain("Alt+ArrowDown");
    expect(shortcutOf("review.deleteOrRestore")).toContain("Delete");
    expect(shortcutOf("export.open")).toContain("Ctrl+E");
    expect(shortcutOf("score.zoomIn")).toEqual(
      expect.arrayContaining(["Ctrl+=", "Ctrl++"]),
    );
    expect(shortcutOf("score.zoomOut")).toContain("Ctrl+-");
    expect(shortcutOf("score.zoomFit")).toContain("Ctrl+0");
    expect(shortcutOf("nav.nextRegion")).toContain("F6");
    expect(shortcutOf("nav.previousRegion")).toContain("Shift+F6");
  });
});

describe("conflict detection", () => {
  const cmd = (over: Partial<Command> & { id: string }): Command => ({
    title: "テスト",
    section: "app",
    run: () => undefined,
    ...over,
  });

  it("detects two commands bound to the same chord", () => {
    const registry = new CommandRegistry([
      cmd({ id: "a.one", shortcuts: ["Ctrl+P"] }),
      cmd({ id: "b.two", shortcuts: ["Ctrl+P"] }),
    ]);
    expect(registry.detectConflicts()).toEqual([
      { shortcut: "Ctrl+P", commandIds: ["a.one", "b.two"] },
    ]);
  });

  it("normalizes bindings before comparing (Ctrl+shift+p == Ctrl+Shift+P)", () => {
    const registry = new CommandRegistry([
      cmd({ id: "a.one", shortcuts: ["Ctrl+Shift+P"] }),
      cmd({ id: "b.two", shortcuts: ["ctrl+shift+p"] }),
    ]);
    expect(registry.detectConflicts()).toHaveLength(1);
  });

  it("detects multi-chord sequence collisions", () => {
    const registry = new CommandRegistry([
      cmd({ id: "a.one", shortcuts: ["Ctrl+K Ctrl+C"] }),
      cmd({ id: "b.two", shortcuts: ["Ctrl+K Ctrl+C"] }),
    ]);
    expect(registry.detectConflicts()).toHaveLength(1);
  });

  it("does not flag two bindings owned by the same command", () => {
    const registry = new CommandRegistry([
      cmd({ id: "a.one", shortcuts: ["Space", "K"] }),
      cmd({ id: "b.two", shortcuts: ["L"] }),
    ]);
    expect(registry.detectConflicts()).toEqual([]);
  });

  it("does not flag a chord vs. a longer sequence sharing its prefix", () => {
    // "Ctrl+K" alone and "Ctrl+K Ctrl+C" coexist: the single chord fires
    // immediately, so this is intentionally strict — they DO conflict at
    // the dispatcher level… except the first chord completes its binding
    // before the sequence can continue. Flagging it keeps authors honest:
    // sequences must not share their first chord with a single binding.
    const registry = new CommandRegistry([
      cmd({ id: "a.one", shortcuts: ["Ctrl+K"] }),
      cmd({ id: "b.two", shortcuts: ["Ctrl+K Ctrl+C"] }),
    ]);
    // Distinct normalized keys — no conflict between the *sequences*, the
    // dispatcher resolves "Ctrl+K" as a full match before any second chord.
    expect(registry.detectConflicts()).toEqual([]);
  });

  it("createCommandRegistry throws when definitions contain a conflict", () => {
    expect(() =>
      createCommandRegistry([
        cmd({ id: "a.one", shortcuts: ["Ctrl+X"] }),
        cmd({ id: "b.two", shortcuts: ["Ctrl+X"] }),
      ]),
    ).toThrow(/conflict/i);
  });

  it("register() rejects a duplicate command id", () => {
    const registry = new CommandRegistry([cmd({ id: "a.one" })]);
    expect(() => registry.register(cmd({ id: "a.one" }))).toThrow(
      /duplicate/i,
    );
  });
});

describe("invoke", () => {
  const registry = createCommandRegistry();

  it("runs an enabled command", () => {
    const ctx = mockContext();
    expect(registry.invoke("file.openAudio", ctx, SNAPSHOT_EMPTY)).toBe(true);
    expect(ctx.calls).toEqual(["openAudio"]);
  });

  it("refuses a disabled command — non-executable from any surface", () => {
    const ctx = mockContext();
    // 採譜 needs audio; EMPTY state has none.
    expect(registry.invoke("score.transcribe", ctx, SNAPSHOT_EMPTY)).toBe(
      false,
    );
    expect(ctx.transcribe).not.toHaveBeenCalled();
  });

  it("returns false for unknown ids", () => {
    const ctx = mockContext();
    expect(registry.invoke("no.such", ctx, SNAPSHOT_EMPTY)).toBe(false);
  });

  it("enables transport/edit/export once a score exists", () => {
    const ctx = mockContext();
    for (const [id, spy] of [
      ["transport.toggleLoop", "toggleLoop"],
      ["edit.undo", "undo"],
      ["export.open", "openExport"],
      ["export.openInMuseScore", "openInMuseScore"],
      ["review.next", null], // needs reviewOpen — stays disabled
    ] as const) {
      const ran = registry.invoke(id, ctx, SNAPSHOT_SCORE);
      if (spy) {
        expect(ran).toBe(true);
        expect(ctx.calls).toContain(spy);
      } else {
        expect(ran).toBe(false);
      }
    }
  });
});

describe("visibility", () => {
  const registry = createCommandRegistry();

  it("review commands stay off surfaces until a review exists", () => {
    const visibleEmpty = registry
      .listVisible(SNAPSHOT_EMPTY)
      .map((c) => c.id);
    expect(visibleEmpty).not.toContain("review.open");
    expect(visibleEmpty).not.toContain("review.next");

    const reviewing: CommandSnapshot = {
      ...SNAPSHOT_SCORE,
      reviewOpen: true,
    };
    const visibleReview = registry
      .listVisible(reviewing)
      .map((c) => c.id);
    expect(visibleReview).toContain("review.open");
    expect(visibleReview).toContain("review.next");
    expect(visibleReview).toContain("review.previous");
  });
});

/**
 * Command model types (docs/GUI_UX_SPEC.md §23).
 *
 * A Command is a *stateless* description: predicates receive a
 * CommandSnapshot so the same definitions can be evaluated for menus,
 * keyboard dispatch, palette listing and tests without re-registering.
 */

/** Pitch display modes (GUI_UX_SPEC §7). Kept literal here so the command
 *  layer does not depend on a component file. */
export type PitchViewSetting = "concert" | "hornF";

/** Top-level screens that gate command availability. */
export type AppView = "workspace" | "settings";

/** Grouping for menus / command palette / docs. */
export type CommandSection =
  | "file"
  | "score"
  | "transport"
  | "view"
  | "review"
  | "edit"
  | "export"
  | "nav"
  | "app";

/**
 * Immutable read of the app state that command predicates evaluate.
 * The app builds one per render; the registry never stores it.
 */
export interface CommandSnapshot {
  /** A source audio file is loaded (GUI_UX_SPEC §4, AUDIO_READY+). */
  readonly hasAudio: boolean;
  /** A canonical score exists (SCORE_READY+). */
  readonly hasScore: boolean;
  /** Transcription is running — score-writing commands disable (§5). */
  readonly isTranscribing: boolean;
  /** Audio is currently playing (drives the play/pause affordance). */
  readonly isPlaying: boolean;
  /** Loop range playback is armed. */
  readonly loopEnabled: boolean;
  /** Current pitch display mode. */
  readonly pitch: PitchViewSetting;
  /** Undo/redo stacks (§14 — all edits are commands). */
  readonly canUndo: boolean;
  readonly canRedo: boolean;
  /** A note/region is selected (gates Esc = clear selection). */
  readonly hasSelection: boolean;
  /** #113: a waveform range selection exists (AUDIO_READY). Esc clears
   *  this before any score selection (spec 8: Esc -> 選択解除). */
  readonly hasWaveformSelection: boolean;
  /** 要確認 workspace state. */
  readonly reviewOpen: boolean;
  readonly reviewCount: number;
  /** FEAT-001: a recording session is in progress (loopback/mic). */
  readonly isRecording: boolean;
  /** FEAT-001 (#80): the recording session is paused. */
  readonly isRecordingPaused: boolean;
  /** FEAT-001: score audition (auto-playback of the score) is on. */
  readonly auditionEnabled: boolean;
  /** Active top-level view. */
  readonly view: AppView;
}

/**
 * The services commands act on. The app supplies implementations; during
 * the spike most are stubs that announce via `announce` so every invocation
 * produces honest feedback in the (aria-live) status bar.
 */
export interface CommandContext {
  openAudio(): void;
  transcribe(): void;
  /**
   * Cooperative `job.cancel` (UI-040): requests cancellation of the
   * in-flight transcription; the job still ends in a terminal `cancelled`
   * event, so callers must not assume an instant stop. Optional so older
   * test contexts keep compiling — an absent implementation is a no-op.
   */
  cancelTranscription?(): void;
  togglePlayPause(): void;
  stop(): void;
  jumpBack(): void;
  jumpForward(): void;
  seekToStart(): void;
  seekToEnd(): void;
  toggleLoop(): void;
  /**
   * FEAT-001 (#60): PC再生音源/マイク録音と楽譜自動演奏。
   * Optional so older test contexts keep compiling.
   */
  captureSystemAudio?(): void;
  captureMicrophone?(): void;
  /** 録音中なら停止して取り込む / 録音していなければ何もしない。 */
  stopCapture?(): void;
  /** 録音を中止して破棄する。 */
  cancelCapture?(): void;
  /** 録音を一時停止する(#80)。 */
  pauseCapture?(): void;
  /** 一時停止した録音を再開する(#80)。 */
  resumeCapture?(): void;
  /** 楽譜の自動演奏トグル(スコアクロックに同期して発音)。 */
  toggleScoreAudition?(): void;
  /** 元音源のミュート切替(#72)。楽譜の演奏だけを聴く用途。 */
  toggleSourceMute?(): void;
  setPitchView(view: PitchViewSetting): void;
  openReview(): void;
  reviewNext(): void;
  reviewPrevious(): void;
  /**
   * UI-050 review-workspace actions (GUI_UX_SPEC §12). Optional like
   * `cancelTranscription` so leaner test contexts keep compiling — an
   * absent implementation is a no-op.
   */
  reviewAccept?(): void;
  reviewDismiss?(): void;
  reviewPlaySource?(): void;
  reviewPitchUp?(): void;
  reviewPitchDown?(): void;
  reviewDeleteOrRestore?(): void;
  exitReview?(): void;
  undo(): void;
  redo(): void;
  openExport(): void;
  /** §13 高度編集: open the live score in the MuseScore GUI (async —
   *  the implementation announces success/failure itself). Optional:
   *  absent = no-op. */
  openInMuseScore?(): void;
  /** #100: プロジェクトを保存 — opens the save-file picker and writes
   *  .hornscribe.json through the engine. Optional like the other
   *  late-binding commands; absent = no-op. */
  saveProject?(): void;
  zoomScoreIn(): void;
  zoomScoreOut(): void;
  zoomScoreFit(): void;
  clearSelection(): void;
  /** #114 (spec 10): select the previous/next note (score workspace). */
  selectAdjacentNote?(direction: 1 | -1): void;
  /** #114 (spec 13): semitone-shift / delete / respell the selected
   *  note outside the review workspace (undoable). */
  editSelectedPitch?(delta: number): void;
  toggleSelectedDeleted?(): void;
  toggleSelectedEnharmonic?(): void;
  /** #113: Esc on a waveform selection (AUDIO_READY) - clears the range
   *  back to "all" (spec 8: Esc -> 選択解除). Optional: absent = no-op. */
  clearWaveformSelection?(): void;
  openSettings(): void;
  /** Opens the 診断情報 sheet (§19 — separated from the normal UI). */
  openDiagnostics(): void;
  /** F6 region navigation — implemented by focus/zones. */
  focusNextRegion(): void;
  focusPreviousRegion(): void;
  /**
   * Surface command feedback in the status area (role="status" is
   * aria-live, so Narrator users hear the result — UX_VALIDATION §11).
   */
  announce(message: string): void;
}

/**
 * A single invocable command — the unit the registry, command bar, menus,
 * palette and keyboard dispatcher all share (single source of truth).
 */
export interface Command {
  /** Stable dotted id, e.g. "transport.playPause". */
  readonly id: string;
  /**
   * Japanese title — the only UI language (UI_COPY_CONTRACT). This is what
   * buttons, menus, a palette and screen readers all announce.
   */
  readonly title: string;
  /** Optional longer Japanese description for palettes/menus. */
  readonly description?: string;
  readonly section: CommandSection;
  /**
   * Keyboard bindings in "Ctrl+Shift+Z" notation; whitespace separates
   * chords in a multi-step sequence. The first entry is the canonical
   * binding shown in tooltips / aria-keyshortcuts.
   */
  readonly shortcuts?: readonly string[];
  /**
   * #114: opt-in to sharing a chord with another command whose
   * `isEnabled` predicate is mutually exclusive (e.g. ArrowRight =
   * review.next while reviewing, score.selectNext otherwise). Every
   * command on the shared chord must set this flag; the dispatcher
   * activates the first *enabled* candidate.
   */
  readonly shareShortcut?: boolean;
  /**
   * May run against this snapshot. Default: enabled. Disabled commands are
   * non-executable everywhere — toolbar, menu AND shortcut (issue req:
   * "disabled commands remain non-executable via shortcut").
   */
  readonly isEnabled?: (snapshot: CommandSnapshot) => boolean;
  /**
   * Listed on command surfaces (palette/menus/overflow). Default: visible.
   * Hidden commands still run when enabled — e.g. 採譜し直す vs 採譜.
   */
  readonly isVisible?: (snapshot: CommandSnapshot) => boolean;
  /** May fire while a text field / IME host has focus. Default false. */
  readonly allowInTextInput?: boolean;
  /** May fire while a modal dialog/sheet owns focus. Default false. */
  readonly allowInModal?: boolean;
  /** Re-fires on key auto-repeat. Default false (no accidental toggles). */
  readonly allowRepeat?: boolean;
  /** Execute against live services. */
  readonly run: (ctx: CommandContext, snapshot: CommandSnapshot) => void;
}

import { Toolbar, ToolbarButton, Tooltip } from "@fluentui/react-components";
import {
  FolderOpen24Regular,
  Play24Regular,
  CheckmarkCircle24Regular,
  ArrowExportUp24Regular,
  Settings24Regular,
  MoreHorizontal24Regular,
  PanelRight24Regular,
  Wrench24Regular,
  Open24Regular,
  Mic24Regular,
  Speaker2Regular,
  Stop24Regular,
  Pause24Regular,
  Dismiss24Regular,
} from "@fluentui/react-icons";
import { ja } from "../strings/ja";
import type { CommandSurface } from "../commands/registry";
import { HsMenu, type HsMenuItem } from "./primitives/Menu";
import { PitchSegmented, type PitchView } from "./PitchSegmented";
import {
  hasWorkspaceRegions,
  type ScreenState,
} from "../workspace/screen";
import type { CaptureState } from "../capture/controller";
import type {
  CaptureDeviceList,
  CaptureSource,
} from "../capture/types";
import { formatTimecode } from "../import/format";

/** 録音経過の短い表示(0:00 形式)。 */
function formatElapsed(seconds: number): string {
  return formatTimecode(seconds);
}

/** Tooltip text: Japanese title plus its canonical shortcut, e.g.
 *  「書き出し（Ctrl+E）」 — shortcut hinting is spec'd on §9 controls. */
function withShortcut(title: string, shortcut?: string): string {
  return shortcut ? `${title}（${shortcut}）` : title;
}

/**
 * Command bar (GUI_UX_SPEC §16, DESIGN_SYSTEM §10).
 * Left: project actions. Center: pitch selector. Right: 要確認/書き出し/設定/overflow.
 * Never scrolls; at <1600px secondary labels collapse to icon+tooltip
 * (§21), at <1200px 設定 moves into the overflow menu. The menu always
 * carries the properties show/close toggle so the panel stays reachable.
 *
 * EMPTY state (§3) hides every score/audio command — only 開く, 設定 and
 * the overflow menu render, so the empty surface stays free of score tools.
 *
 * Every action routes through the command surface (§23): enabled state,
 * Japanese label and shortcut all come from the registry, so the button,
 * the menu item and the keyboard binding can never disagree.
 */
export function CommandBar({
  commands,
  pitch,
  screen,
  reviewCount,
  compact,
  propertiesOpen,
  onToggleProperties,
  captureState,
  captureDevices,
  captureSelectedDevice,
  onSelectCaptureDevice,
  onCaptureMenuOpen,
}: {
  commands: CommandSurface;
  pitch: PitchView;
  screen: ScreenState;
  reviewCount: number;
  /** <1200px breakpoint — 設定 lives in the overflow menu instead. */
  compact: boolean;
  propertiesOpen: boolean;
  onToggleProperties(): void;
  /** FEAT-001 (#60): live capture state for the recording affordance. */
  captureState?: CaptureState | null;
  /** #73: 取り込みデバイス一覧(メニュー開時に最新化される)。 */
  captureDevices?: CaptureDeviceList | null;
  /** 選択中のデバイス ID(null = 既定)。 */
  captureSelectedDevice?(source: CaptureSource): string | null;
  onSelectCaptureDevice?(source: CaptureSource, id: string | null): void;
  /** メニューが開いた時にデバイス一覧を取り直す。 */
  onCaptureMenuOpen?(): void;
}) {
  // 採譜 ↔ 採譜し直す — same command slot, label follows score presence
  // (the registry hides retranscribe until a score exists).
  const transcribeId = "score.transcribe";
  const retranscribeId = "score.retranscribe";
  const transcribe = commands.isVisible(retranscribeId)
    ? retranscribeId
    : transcribeId;

  const onPitch = (v: PitchView) =>
    commands.invoke(v === "concert" ? "view.concertPitch" : "view.hornF");

  // EMPTY and the import error states (§3/§20) keep the command bar to
  // shell actions only — no score/audio commands without a live context.
  const loaded = hasWorkspaceRegions(screen);
  const hasScore =
    screen === "scoreReady" || screen === "reviewing" || screen === "exporting";
  const transcribeTooltip = hasScore
    ? ja.commandBar.retranscribeTooltip
    : ja.commandBar.transcribeTooltip;
  const reviewLabel =
    reviewCount > 0
      ? ja.commandBar.reviewWithCount.replace("{count}", String(reviewCount))
      : ja.commandBar.review;

  const overflowItems: HsMenuItem[] = [
    ...(compact
      ? [
          {
            key: "settings",
            label: commands.title("app.settings"),
            icon: <Settings24Regular />,
          } satisfies HsMenuItem,
        ]
      : []),
    {
      key: "properties",
      label: propertiesOpen ? ja.properties.close : ja.properties.show,
      icon: <PanelRight24Regular />,
    },
    // §13 高度編集: hand the live score to MuseScore (score only — the
    // item hides on import screens like the 書き出し button does).
    ...(hasScore
      ? [
          {
            key: "musescore",
            label: commands.title("export.openInMuseScore"),
            icon: <Open24Regular />,
            disabled: !commands.isEnabled("export.openInMuseScore"),
          } satisfies HsMenuItem,
        ]
      : []),
    { key: "overflow-divider", divider: true },
    // §16: diagnostics lives in the overflow, never on the command bar.
    {
      key: "diagnostics",
      label: commands.title("app.diagnostics"),
      icon: <Wrench24Regular />,
    },
  ];

  // FEAT-001: capture menu lives next to 開く — sources of new audio.
  // #73: 各ソースの下にそのソースのデバイス選択を並べる。選択中は ✓。
  const deviceItems = (
    source: CaptureSource,
    devices: readonly { id: string; name: string; isDefault: boolean }[],
  ): HsMenuItem[] => {
    // デバイスが1台も無いソース(ブラウザ dev の loopback 等)は
    // セクション自体を出さない — 既定しか選べない行は誤解を招く。
    if (devices.length === 0) return [];
    const selected = captureSelectedDevice?.(source) ?? null;
    const sectionLabel =
      source === "loopback"
        ? ja.capture.loopbackDeviceLabel
        : ja.capture.microphoneDeviceLabel;
    const items: HsMenuItem[] = [
      { key: source + "-hdr", label: sectionLabel, disabled: true },
      {
        key: source + ":default",
        label:
          selected === null
            ? "\u2713 " + ja.capture.defaultDevice
            : ja.capture.defaultDevice,
      },
    ];
    for (const d of devices) {
      items.push({
        key: source + ":" + d.id,
        label: selected === d.id ? "\u2713 " + d.name : d.name,
      });
    }
    return items;
  };
  const captureMenuItems: HsMenuItem[] = [
    {
      key: "loopback",
      label: commands.title("media.captureSystemAudio"),
      icon: <Speaker2Regular />,
      disabled: !commands.isEnabled("media.captureSystemAudio"),
    },
    {
      key: "microphone",
      label: commands.title("media.captureMicrophone"),
      icon: <Mic24Regular />,
      disabled: !commands.isEnabled("media.captureMicrophone"),
    },
    // デバイスセクションは一覧が取れた時だけ出す(ブラウザ dev では
    // loopback は空、mic のみ)。両方空なら区切り線ごと出さない。
    ...(captureDevices &&
    (captureDevices.loopback.length > 0 ||
      captureDevices.microphone.length > 0)
      ? ([
          { key: "devices-divider", divider: true },
          ...deviceItems("loopback", captureDevices.loopback),
          ...deviceItems("microphone", captureDevices.microphone),
        ] satisfies HsMenuItem[])
      : []),
  ];
  const recording = captureState?.phase === "recording";
  const captureLabel =
    recording && captureState?.source === "loopback"
      ? ja.transport.recordingLoopbackLabel
      : recording
        ? ja.transport.recordingLabel
        : "取り込み";

  return (
    <Toolbar
      className="hs-commandbar"
      aria-label={ja.commandBar.regionLabel}
      data-hs-focus-zone="commandbar"
      tabIndex={-1}
    >
      <Tooltip content={ja.commandBar.openTooltip} relationship="label">
        <ToolbarButton
          icon={<FolderOpen24Regular />}
          disabled={!commands.isEnabled("file.openAudio")}
          aria-keyshortcuts="Control+O"
          onClick={() => commands.invoke("file.openAudio")}
        >
          <span className="hs-commandbar__label">{ja.commandBar.openLabel}</span>
        </ToolbarButton>
      </Tooltip>
      {loaded ? (
        <Tooltip content={transcribeTooltip} relationship="label">
          <ToolbarButton
            icon={<Play24Regular />}
            disabled={!commands.isEnabled(transcribe)}
            appearance="primary"
            onClick={() => commands.invoke(transcribe)}
          >
            <span className="hs-commandbar__label">
              {commands.title(transcribe)}
            </span>
          </ToolbarButton>
        </Tooltip>
      ) : null}

      {loaded ? <span className="hs-commandbar__spacer" /> : null}
      {loaded ? <PitchSegmented value={pitch} onChange={onPitch} /> : null}
      <span className="hs-commandbar__spacer" />

      {/* FEAT-001: 録音ソース — EMPTY/READY どちらでも新しい音源を取り込める。
          録音中は「停止して取り込む」「やめる」の 2 操作に切り替わる。 */}
      {!recording ? (
        <HsMenu
          trigger={
            <ToolbarButton icon={<Mic24Regular />} aria-label={captureLabel}>
              <span className="hs-commandbar__label">{captureLabel}</span>
            </ToolbarButton>
          }
          items={captureMenuItems}
          ariaLabel={captureLabel}
          onOpenChange={(open) => {
            if (open) onCaptureMenuOpen?.();
          }}
          onSelect={(key) => {
            if (key === "loopback") commands.invoke("media.captureSystemAudio");
            else if (key === "microphone") commands.invoke("media.captureMicrophone");
            else if (key === "loopback:default")
              onSelectCaptureDevice?.("loopback", null);
            else if (key === "microphone:default")
              onSelectCaptureDevice?.("microphone", null);
            else if (key.startsWith("loopback:"))
              onSelectCaptureDevice?.("loopback", key.slice("loopback:".length));
            else if (key.startsWith("microphone:"))
              onSelectCaptureDevice?.(
                "microphone",
                key.slice("microphone:".length),
              );
          }}
        />
      ) : (
        <>
          <Tooltip content={commands.title("media.stopCapture")} relationship="label">
            <ToolbarButton
              icon={<Stop24Regular />}
              appearance="primary"
              aria-keyshortcuts="Ctrl+Enter"
              onClick={() => commands.invoke("media.stopCapture")}
            >
              <span className="hs-commandbar__label">
                {commands.title("media.stopCapture")}
                {captureState?.elapsedSeconds != null
                  ? ` ${formatElapsed(captureState.elapsedSeconds)}`
                  : ""}
                {captureState?.paused ? ` — ${ja.capture.pausedLabel}` : ""}
              </span>
            </ToolbarButton>
          </Tooltip>
          {/* #80: 一時停止/再開 — paused 中はアイコンと対象コマンドが
              切り替わる。停止・中止は paused 中もそのまま使える。 */}
          {captureState?.paused ? (
            <Tooltip content={commands.title("media.resumeCapture")} relationship="label">
              <ToolbarButton
                icon={<Play24Regular />}
                aria-label={commands.title("media.resumeCapture")}
                onClick={() => commands.invoke("media.resumeCapture")}
              />
            </Tooltip>
          ) : (
            <Tooltip content={commands.title("media.pauseCapture")} relationship="label">
              <ToolbarButton
                icon={<Pause24Regular />}
                aria-label={commands.title("media.pauseCapture")}
                onClick={() => commands.invoke("media.pauseCapture")}
              />
            </Tooltip>
          )}
          <Tooltip content={commands.title("media.cancelCapture")} relationship="label">
            <ToolbarButton
              icon={<Dismiss24Regular />}
              onClick={() => commands.invoke("media.cancelCapture")}
            />
          </Tooltip>
        </>
      )}

      {loaded ? (
        <Tooltip content={reviewLabel} relationship="label">
          <ToolbarButton
            icon={<CheckmarkCircle24Regular />}
            disabled={!commands.isEnabled("review.open")}
            onClick={() => commands.invoke("review.open")}
          >
            <span className="hs-commandbar__label">{reviewLabel}</span>
          </ToolbarButton>
        </Tooltip>
      ) : null}
      {loaded ? (
        <Tooltip
          content={withShortcut(
            ja.commandBar.exportTooltip,
            commands.shortcutLabel("export.open"),
          )}
          relationship="label"
        >
          <ToolbarButton
            icon={<ArrowExportUp24Regular />}
            disabled={!commands.isEnabled("export.open")}
            aria-keyshortcuts="Control+E"
            onClick={() => commands.invoke("export.open")}
          >
            <span className="hs-commandbar__label">
              {commands.title("export.open")}
            </span>
          </ToolbarButton>
        </Tooltip>
      ) : null}
      {!compact && commands.isEnabled("app.settings") ? (
        <Tooltip
          content={commands.title("app.settings")}
          relationship="label"
        >
          <ToolbarButton
            icon={<Settings24Regular />}
            onClick={() => commands.invoke("app.settings")}
          />
        </Tooltip>
      ) : null}
      <HsMenu
        trigger={
          <ToolbarButton
            icon={<MoreHorizontal24Regular />}
            aria-label={ja.commandBar.overflow}
          />
        }
        items={overflowItems}
        ariaLabel={ja.commandBar.overflow}
        onSelect={(key) => {
          if (key === "settings") commands.invoke("app.settings");
          else if (key === "properties") onToggleProperties();
          else if (key === "musescore")
            commands.invoke("export.openInMuseScore");
          else if (key === "diagnostics") commands.invoke("app.diagnostics");
        }}
      />
    </Toolbar>
  );
}

/**
 * MockExportPort — in-process emulation of the export backend so the §17
 * flow (formats, MuseScore gating, destination, progress, done/error
 * recovery) is exercisable in `vite dev` and vitest without a real engine.
 *
 * The fake reports an engine identity honestly labelled "(mock)" — the
 * diagnostics surface never pretends a real engine answered.
 *
 * Dev overrides (browser only, read once at construction):
 *   localStorage["hornscribe.dev.museScore"] === "missing"  → MuseScore
 *     reports missing so the PDF-disabled recovery path is reviewable;
 *   localStorage["hornscribe.dev.exportFailure"] in
 *     {"permission","engine","musescore","failed"}          → export()
 *     always rejects with the matching ExportError code so the error
 *     phases are reachable from the UI.
 */

import {
  withPathOverride,
  type EngineInfo,
  type ToolInfo,
  type ToolPathOverrides,
} from "../diagnostics/types";
import {
  ExportError,
  EXPORT_FORMAT_IDS,
  type ExportCapabilities,
  type ExportErrorCode,
  type ExportFormatId,
  type ExportPort,
  type ExportRequest,
  type ExportResult,
} from "./types";
import type { ExportedFile } from "./types";

/** ENG-001 filename policy: `<basename>_<artifact>`. */
const ARTIFACT_NAMES: Record<ExportFormatId, string> = {
  concertMusicxml: "concert.musicxml",
  hornMusicxml: "horn_in_f.musicxml",
  concertPdf: "concert.pdf",
  hornPdf: "horn_in_f.pdf",
  playbackMidi: "playback.mid",
  sourceAudio: "source.wav",
};

const MOCK_ENGINE: EngineInfo = {
  name: "hornscribe-engine (mock)",
  version: "0.1.0",
  python: "3.12.x",
  platform: "win32",
};

const DEV_MUSESCORE_KEY = "hornscribe.dev.museScore";
const DEV_FAILURE_KEY = "hornscribe.dev.exportFailure";

const DEV_FAILURE_CODES: Record<string, ExportErrorCode> = {
  permission: "PERMISSION_DENIED",
  engine: "ENGINE_UNAVAILABLE",
  musescore: "MUSESCORE_UNAVAILABLE",
  failed: "EXPORT_FAILED",
};

export interface MockExportPortOptions {
  museScore?: ToolInfo;
  ffmpeg?: ToolInfo;
  /** Simulated audioAvailable capability (#87) — default true. */
  audioAvailable?: boolean;
  /** Simulated latency for capabilities()/export(). */
  latencyMs?: number;
  /** Deterministic failure for export() — recovery-path tests. */
  failure?: ExportErrorCode;
  defaultDestination?: string;
}

export class MockExportPort implements ExportPort {
  private readonly options: Required<
    Pick<MockExportPortOptions, "latencyMs" | "defaultDestination">
  > &
    MockExportPortOptions;

  constructor(options: MockExportPortOptions = {}) {
    this.options = { latencyMs: 450, defaultDestination: "", ...options };
  }

  /** Browser-dev factory: honours the localStorage dev flags above. */
  static withDevOverrides(): MockExportPort {
    let museScore: ToolInfo | undefined;
    let failure: ExportErrorCode | undefined;
    try {
      if (window.localStorage.getItem(DEV_MUSESCORE_KEY) === "missing") {
        museScore = { status: "missing" };
      }
      const f = window.localStorage.getItem(DEV_FAILURE_KEY);
      if (f && f in DEV_FAILURE_CODES) failure = DEV_FAILURE_CODES[f];
    } catch {
      /* localStorage may be unavailable — defaults are fine */
    }
    return new MockExportPort({ museScore, failure });
  }

  private delay(): Promise<void> {
    return new Promise((r) => setTimeout(r, this.options.latencyMs));
  }

  async capabilities(
    overrides?: ToolPathOverrides,
  ): Promise<ExportCapabilities> {
    await this.delay();
    const museScore =
      this.options.museScore ??
      ({
        status: "found",
        path: "C:\\Program Files\\MuseScore 4\\bin\\MuseScore4.exe",
        version: "4.x",
      } satisfies ToolInfo);
    const ffmpeg =
      this.options.ffmpeg ??
      ({
        status: "found",
        path: "C:\\tools\\ffmpeg\\bin\\ffmpeg.exe",
        version: "7.x",
      } satisfies ToolInfo);
    return {
      engineInfo: MOCK_ENGINE,
      protocolVersion: 1,
      backend: "basic-pitch (mock)",
      museScore: withPathOverride(museScore, overrides?.museScorePath),
      ffmpeg: withPathOverride(ffmpeg, overrides?.ffmpegPath),
      audioAvailable: this.options.audioAvailable ?? true,
    };
  }

  async chooseDestination(current?: string): Promise<string | null> {
    await this.delay();
    // A browser has no native picker — the mock "chooses" deterministically
    // so the destination row exercises the populated state.
    return current ?? (this.options.defaultDestination || this.fallbackDir());
  }

  async defaultDestination(): Promise<string> {
    return this.options.defaultDestination || this.fallbackDir();
  }

  private fallbackDir(): string {
    return "C:\\Users\\user\\Documents\\HornScribe";
  }

  async export(request: ExportRequest): Promise<ExportResult> {
    await this.delay();
    const failure = this.options.failure;
    if (failure) {
      throw new ExportError(failure, `mock export failure: ${failure}`);
    }
    if (request.formats.length === 0) {
      throw new ExportError("EXPORT_FAILED", "no formats selected");
    }
    const basename = request.basename?.trim() || "score";
    const dir = request.destination;
    const files: ExportedFile[] = EXPORT_FORMAT_IDS.filter((f) =>
      request.formats.includes(f),
    ).map((format) => {
      const artifact = ARTIFACT_NAMES[format];
      const name = `${basename}_${artifact}`;
      return { format, name, path: `${dir}\\${name}` };
    });
    return { destination: dir, files };
  }

  async revealInExplorer(): Promise<boolean> {
    // No OS bridge in a browser — honest false; the dialog announces it.
    return false;
  }

  /** §13 高度編集: the mock honours the same MuseScore-missing dev flag
   *  so the recovery announce is reviewable in `vite dev`; otherwise it
   *  resolves a fake staged path (no GUI exists in a browser). */
  async openInMuseScore(): Promise<string> {
    await this.delay();
    const missing =
      this.options.museScore != null &&
      this.options.museScore.status !== "found";
    if (missing) {
      throw new ExportError(
        "MUSESCORE_UNAVAILABLE",
        "MuseScore not found (mock)",
      );
    }
    return "C:\\Temp\\hornscribe-open-mock.musicxml";
  }
}

/**
 * TauriExportPort — the real export backend inside the Tauri webview
 * (#99). MusicXML and MIDI are produced entirely client-side from the
 * live score document (user edits included via musicXml(view)); PDF
 * renders through a detected MuseScore install. No engine process is
 * required for any format.
 *
 * Rust commands (src-tauri/src/export.rs) own the privileged halves:
 * folder picking, artifact writes (granted-dir allowlist), tool
 * probing, explorer reveal and the MuseScore subprocess.
 */
import { invoke } from "@tauri-apps/api/core";
import {
  withPathOverride,
  type ToolInfo,
  type ToolPathOverrides,
} from "../diagnostics/types";
import type { ScoreDocumentPort } from "../score/document";
import { buildMidiFile } from "./midi";
import {
  ExportError,
  type ExportCapabilities,
  type ExportFormatId,
  type ExportPort,
  type ExportRequest,
  type ExportResult,
  type ExportedFile,
} from "./types";

/** ENG-001 filename policy shared with the mock port. */
const ARTIFACT_NAMES: Record<ExportFormatId, string> = {
  concertMusicxml: "concert.musicxml",
  hornMusicxml: "horn_in_f.musicxml",
  concertPdf: "concert.pdf",
  hornPdf: "horn_in_f.pdf",
  playbackMidi: "playback.mid",
  // The real artifact keeps the source's own extension — this is only
  // the display-name fallback when the copy result has no file name.
  sourceAudio: "source.wav",
};

/** What the port needs from the app at export time. */
export interface ExportSource {
  /** Live score document (XML bodies + meta); null = nothing to export. */
  readonly doc: ScoreDocumentPort | null;
  /** Default file basename — audio file stem or score title. */
  readonly basename: string;
  /** Absolute path of the loaded audio when it lives on disk — enables
   *  the sourceAudio bundle format (#87). Null for browser-held bytes. */
   readonly audioPath: string | null;
  /** Original audio file name (extension kept) for the bundle copy. */
   readonly audioName: string | null;
}

interface DetectedToolWire {
  status: string;
  path?: string;
}
interface DetectedToolsWire {
  museScore: DetectedToolWire;
  ffmpeg: DetectedToolWire;
}

function toToolInfo(wire: DetectedToolWire): ToolInfo {
  return wire.status === "found"
    ? { status: "found", path: wire.path }
    : { status: "missing" };
}

/** UTF-8-safe base64 (btoa chokes on multibyte; chunk to stay under the
 *  String.fromCharCode arg limit). */
function toBase64(bytes: Uint8Array): string {
  let bin = "";
  const CHUNK = 0x8000;
  for (let i = 0; i < bytes.length; i += CHUNK) {
    bin += String.fromCharCode(...bytes.subarray(i, i + CHUNK));
  }
  return btoa(bin);
}

function textToBase64(text: string): string {
  return toBase64(new TextEncoder().encode(text));
}

/** Filesystem-safe basename: strip separators and illegal chars. */
function sanitizeBasename(raw: string): string {
  const cleaned = raw
    .replace(/[\\/:*?"<>|]/g, "_")
    .replace(/\.+$/, "")
    .trim();
  return cleaned || "score";
}

function mapInvokeError(err: unknown): ExportError {
  const msg = err instanceof Error ? err.message : String(err);
  if (msg.includes("PERMISSION_DENIED")) {
    return new ExportError("PERMISSION_DENIED", msg);
  }
  if (msg.includes("MUSESCORE_UNAVAILABLE")) {
    return new ExportError("MUSESCORE_UNAVAILABLE", msg);
  }
  return new ExportError("EXPORT_FAILED", msg);
}

export class TauriExportPort implements ExportPort {
  /** Last tool-path overrides seen by capabilities() — reused by the
   *  PDF branch of export() so a user-specified MuseScore path wins. */
  private overrides?: ToolPathOverrides;

  constructor(private readonly source: () => ExportSource | null) {}

  async capabilities(
    overrides?: ToolPathOverrides,
  ): Promise<ExportCapabilities> {
    this.overrides = overrides;
    const tools = await invoke<DetectedToolsWire>("detect_tools").catch(
      () => null,
    );
    const museScore = withPathOverride(
      tools ? toToolInfo(tools.museScore) : { status: "missing" },
      overrides?.museScorePath,
    );
    const ffmpeg = withPathOverride(
      tools ? toToolInfo(tools.ffmpeg) : { status: "missing" },
      overrides?.ffmpegPath,
    );
    return {
      // Client-side export needs no engine — report that honestly
      // rather than faking a handshake.
      engineInfo: null,
      protocolVersion: null,
      backend: null,
      museScore,
      ffmpeg,
      audioAvailable: this.source()?.audioPath != null,
    };
  }

  async chooseDestination(current?: string): Promise<string | null> {
    try {
      return await invoke<string | null>("export_pick_dir", {
        current: current ?? null,
      });
    } catch (err) {
      throw mapInvokeError(err);
    }
  }

  async defaultDestination(): Promise<string> {
    try {
      return await invoke<string>("export_default_dir");
    } catch (err) {
      throw mapInvokeError(err);
    }
  }

  async export(request: ExportRequest): Promise<ExportResult> {
    const source = this.source();
    if (!source?.doc) {
      throw new ExportError("EXPORT_FAILED", "no score document to export");
    }
    const basename = sanitizeBasename(
      request.basename?.trim() || source.basename || source.doc.meta.title,
    );
    const dir = request.destination;
    const files: ExportedFile[] = [];

    // #87: bundle the source audio itself — a straight fs copy through
    // export_copy_audio (no base64 round-trip for what can be a large
    // file). Runs first so a missing source fails before partial
    // artifacts are written.
    if (request.formats.includes("sourceAudio") && source.audioPath) {
      try {
        const path = await invoke<string>("export_copy_audio", {
          src: source.audioPath,
          dir,
          basename,
        });
        files.push({
          format: "sourceAudio",
          name: path.split(/[\\/]/).pop() ?? `${basename}.wav`,
          path,
        });
      } catch (err) {
        throw mapInvokeError(err);
      }
    }

    // Text/binary artifacts first (single batched write call).
    const batch: { format: ExportFormatId; name: string; dataBase64: string }[] = [];
    for (const format of request.formats) {
      const name = `${basename}_${ARTIFACT_NAMES[format]}`;
      if (format === "concertMusicxml") {
        batch.push({ format, name, dataBase64: textToBase64(source.doc.musicXml("concert")) });
      } else if (format === "hornMusicxml") {
        batch.push({ format, name, dataBase64: textToBase64(source.doc.musicXml("hornF")) });
      } else if (format === "playbackMidi") {
        batch.push({
          format,
          name,
          dataBase64: toBase64(buildMidiFile(source.doc.musicXml("concert"))),
        });
      }
    }
    if (batch.length > 0) {
      let paths: string[];
      try {
        paths = await invoke<string[]>("export_write_files", {
          dir,
          files: batch.map((f) => ({ name: f.name, dataBase64: f.dataBase64 })),
        });
      } catch (err) {
        throw mapInvokeError(err);
      }
      batch.forEach((f, i) =>
        files.push({ format: f.format, name: f.name, path: paths[i] ?? `${dir}\\${f.name}` }),
      );
    }

    // PDFs render through MuseScore — gated by the probe the dialog
    // already ran (a missing tool surfaces as MUSESCORE_UNAVAILABLE).
    const pdfFormats = request.formats.filter(
      (f) => f === "concertPdf" || f === "hornPdf",
    );
    if (pdfFormats.length > 0) {
      const caps = await this.capabilities(this.overrides);
      const exe = caps.museScore.status === "found" ? caps.museScore.path : null;
      if (!exe) {
        throw new ExportError(
          "MUSESCORE_UNAVAILABLE",
          "MuseScore not found; PDF export is unavailable",
        );
      }
      for (const format of pdfFormats) {
        const name = `${basename}_${ARTIFACT_NAMES[format]}`;
        const xml = source.doc.musicXml(format === "hornPdf" ? "hornF" : "concert");
        try {
          const path = await invoke<string>("render_pdf", {
            musescorePath: exe,
            musicXml: xml,
            outPath: `${dir}\\${name}`,
          });
          files.push({ format, name, path });
        } catch (err) {
          throw mapInvokeError(err);
        }
      }
    }

    return { destination: dir, files };
  }

  async revealInExplorer(path: string): Promise<boolean> {
    try {
      await invoke("reveal_in_explorer", { path });
      return true;
    } catch {
      return false;
    }
  }

  /** §13 高度編集: hand the live score to the MuseScore GUI. The view
   *  argument picks concert vs F管 written pitch — the same document the
   *  user is looking at, edits included. */
  async openInMuseScore(
    view: "concert" | "hornF",
    overrides?: ToolPathOverrides,
  ): Promise<string> {
    const source = this.source();
    if (!source?.doc) {
      throw new ExportError("EXPORT_FAILED", "no score document to open");
    }
    const caps = await this.capabilities(overrides ?? this.overrides);
    const exe = caps.museScore.status === "found" ? caps.museScore.path : null;
    if (!exe) {
      throw new ExportError(
        "MUSESCORE_UNAVAILABLE",
        "MuseScore not found; set its path in 設定 → ツール",
      );
    }
    try {
      return await invoke<string>("open_in_musescore", {
        musescorePath: exe,
        musicXml: source.doc.musicXml(view),
        basename: source.basename || source.doc.meta.title,
      });
    } catch (err) {
      throw mapInvokeError(err);
    }
  }
}

/**
 * Export contract types (UI-060; GUI_UX_SPEC §17; ENG-001 semantics).
 *
 * The dialog talks to a typed {@link ExportPort} (port.ts) — the same
 * port/gate layering the sidecar client uses (`src/sidecar/port.ts` in
 * UI-040): a mock port makes the whole UX exercisable in a plain browser,
 * while a real engine reports the same capability surface through the
 * `engine.handshake` response once the spawn bridge lands.
 */

import type {
  EngineInfo,
  ToolInfo,
  ToolPathOverrides,
} from "../diagnostics/types";

/**
 * The five export choices of §17. ENG-001 semantics:
 * - `concertMusicxml` / `hornMusicxml` → `*_concert.musicxml` /
 *   `*_horn_in_f.musicxml`; the F管ホルン artifact carries written pitches
 *   plus the -P5 `<transpose>` element so readers recover sounding pitch;
 * - `playbackMidi` → `*_playback.mid`, always *sounding* (concert) pitch —
 *   SMF has no transposing-instrument semantics, so a written-pitch MIDI
 *   would be ambiguous about its own pitch space (再生用MIDIは実音);
 * - `concertPdf` / `hornPdf` → rendered through MuseScore, hence gated by
 *   the MuseScore tool capability.
 * - `sourceAudio` → the original audio file copied alongside the score
 *   artifacts (#87 成果物同梱): a recording→score bundle stays usable
 *   outside the app. Gated by `capabilities.audioAvailable` — only refs
 *   backed by a real path can be copied.
 */
export type ExportFormatId =
  | "concertMusicxml"
  | "hornMusicxml"
  | "concertPdf"
  | "hornPdf"
  | "playbackMidi"
  | "sourceAudio";

/** Checkbox grouping from the spec mock-up (楽譜 / PDF / MIDI / 音声). */
export type ExportFormatGroup = "score" | "pdf" | "midi" | "audio";

export const EXPORT_FORMAT_GROUPS: Record<ExportFormatId, ExportFormatGroup> = {
  concertMusicxml: "score",
  hornMusicxml: "score",
  concertPdf: "pdf",
  hornPdf: "pdf",
  playbackMidi: "midi",
  sourceAudio: "audio",
};

export const EXPORT_FORMAT_IDS: readonly ExportFormatId[] = [
  "concertMusicxml",
  "hornMusicxml",
  "concertPdf",
  "hornPdf",
  "playbackMidi",
  "sourceAudio",
];

/**
 * The capability surface the export dialog needs — a subset of the engine
 * handshake plus local tool detection (MuseScore drives PDF availability;
 * FFmpeg is reported for consistency with diagnostics).
 */
export interface ExportCapabilities {
  readonly engineInfo: EngineInfo | null;
  readonly protocolVersion: number | null;
  /** Transcription backend id when known (diagnostics parity). */
  readonly backend: string | null;
  readonly museScore: ToolInfo;
  readonly ffmpeg: ToolInfo;
  /** True when the loaded audio is backed by a real path and can be
   *  copied into the export bundle (sourceAudio format, #87). */
  readonly audioAvailable: boolean;
}

/** PDF export requires MuseScore; everything else stays available (§17). */
export function pdfBlocked(capabilities: ExportCapabilities): boolean {
  return capabilities.museScore.status !== "found";
}

/** A single written artifact returned by a successful export. */
export interface ExportedFile {
  readonly format: ExportFormatId;
  /** Absolute path of the written file. */
  readonly path: string;
  /** File name only (for display). */
  readonly name: string;
}

export interface ExportRequest {
  /** Formats to write — at least one, all enabled by capabilities. */
  readonly formats: readonly ExportFormatId[];
  /** Destination directory (absolute path). */
  readonly destination: string;
  /** Document base name for `<basename>_<artifact>` naming (ENG-001). */
  readonly basename?: string;
}

export interface ExportResult {
  readonly destination: string;
  readonly files: readonly ExportedFile[];
}

/**
 * Stable error codes the UI maps onto Japanese recovery copy — raw engine
 * messages and stack traces never reach the dialog (§20, acceptance:
 * "technical stack trace is not shown in normal error UI").
 */
export type ExportErrorCode =
  /** Destination is not writable (permission / read-only). */
  | "PERMISSION_DENIED"
  /** No engine connected (sidecar not spawned / crashed). */
  | "ENGINE_UNAVAILABLE"
  /** PDF was requested without a usable MuseScore. */
  | "MUSESCORE_UNAVAILABLE"
  /** Anything else — generic failure with retry/choose-destination. */
  | "EXPORT_FAILED";

export class ExportError extends Error {
  readonly code: ExportErrorCode;
  constructor(code: ExportErrorCode, message: string) {
    super(message);
    this.name = "ExportError";
    this.code = code;
  }
}

/** Maps an unknown thrown value to a stable code for the dialog. */
export function exportErrorCode(err: unknown): ExportErrorCode {
  if (err instanceof ExportError) return err.code;
  return "EXPORT_FAILED";
}

/**
 * ExportPort — the seam between the 書き出し dialog and a concrete export
 * backend (see port.ts for the runtime gate). Declared here with the rest
 * of the contract so implementations never import the port module itself.
 */
export interface ExportPort {
  /**
   * Probe export-relevant capabilities: engine identity, protocol version,
   * backend and tool detection. `overrides` carries the user-specified tool
   * paths from 設定 → ツール/書き出し (non-empty paths win over probing).
   * Rejects with ExportError(ENGINE_UNAVAILABLE) when no engine/backend
   * can answer — the dialog shows the recovery surface, not a crash.
   */
  capabilities(overrides?: ToolPathOverrides): Promise<ExportCapabilities>;
  /**
   * Ask the user for a destination directory (native picker where a real
   * bridge exists). Resolves null when the picker was cancelled.
   */
  chooseDestination(current?: string): Promise<string | null>;
  /**
   * The directory preselected in the dialog: the 設定 → 書き出し default
   * when set, else the engine/OS documents location.
   */
  defaultDestination(): Promise<string>;
  /**
   * Run the export. Resolves with the written artifacts; rejects with a
   * typed {@link ExportError} whose code drives the §20 recovery surface —
   * raw engine output/stack traces stay behind the port.
   */
  export(request: ExportRequest): Promise<ExportResult>;
  /**
   * Reveal a directory in the OS file manager (エクスプローラーで表示).
   * Resolves false where the bridge cannot do that — the caller announces
   * the failure instead of pretending.
   */
  revealInExplorer(path: string): Promise<boolean>;
  /**
   * §13 高度編集: open the live score (user edits included) in the
   * MuseScore GUI — stages the current view's MusicXML to a temp file
   * and launches the detected/user-pinned executable. Resolves the
   * staged path; rejects with ExportError(MUSESCORE_UNAVAILABLE) when
   * no MuseScore is usable. Optional so browser/mock ports and leaner
   * test doubles keep compiling — an absent implementation is a no-op.
   */
  openInMuseScore?(
    view: "concert" | "hornF",
    overrides?: ToolPathOverrides,
  ): Promise<string>;
}
